d = json.load(open(sys.argv[1]))
c = d['components']
print('notable nonempty', sum(1 for v in c.values() if v['notableInherited']))
print('with layers', sum(1 for v in c.values() if v['inheritance']))
for k, v in c.items():
    if v['inheritance']:
        print(k, json.dumps(v['inheritance'])[:700])
        print('props', [d['props'][p]['name'] if p in d['props'] else d['propSets'].get(p) for p in v['props']][:5])
        break
for k, v in c.items():
    if v['notableInherited']:
        print(k, json.dumps(v['notableInherited'])[:500]); break
ks = {}
for v in c.values():
    for l in v['inheritance']:
        ks.setdefault(str(l.get('htmlElement')), 0)
        ks[str(l.get('htmlElement'))] += 1
print(ks)

