// usage: node callsites.mjs <repoRoot> <out.json>
// Walks every .tsx/.jsx under repoRoot (skipping node_modules), resolves each capitalised JSX tag by import/export identity
// to a chain of (file, exportName) positions, and records the attribute names passed. Resolution is syntactic:
// TS module resolution (tsconfig paths) with a workspace-package fallback, then re-export chains are followed by parsing.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
const require = createRequire('/Users/gabe/Projects/caliper-fixtures/oracle-local/apps/oracle/');
const ts = require('/Users/gabe/Projects/caliper-fixtures/oracle-local/apps/oracle/node_modules/typescript');

const root = path.resolve(process.argv[2]);
const outFile = process.argv[3];
const SKIP = new Set(['node_modules', '.git', 'dist', 'build', '.next', '.turbo', '.cache']);
const jsxFiles = [], stories = [], pkgs = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isSymbolicLink()) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) { if (!SKIP.has(e.name)) walk(p); }
    else if (/\.(tsx|jsx)$/.test(e.name) && !/\.d\.ts$/.test(e.name)) { jsxFiles.push(p); if (/\.stories\./.test(e.name)) stories.push(p); }
    else if (/\.stories\.(ts|js|mdx)$/.test(e.name)) stories.push(p);
    else if (e.name === 'package.json') pkgs.push(p);
  }
})(root);

// workspace packages: name -> dir
const ws = new Map();
for (const p of pkgs) {
  try { const j = JSON.parse(fs.readFileSync(p, 'utf8')); if (j.name) ws.set(j.name, path.dirname(p)); } catch {}
}
const wsNames = [...ws.keys()].sort((a, b) => b.length - a.length);

const cfgCache = new Map();
function optionsFor(file) {
  let dir = path.dirname(file);
  while (dir.startsWith(root)) {
    const c = path.join(dir, 'tsconfig.json');
    if (fs.existsSync(c)) {
      if (!cfgCache.has(c)) {
        let opts = {};
        try {
          const raw = ts.readConfigFile(c, ts.sys.readFile);
          const host = { ...ts.sys, readDirectory: () => [], useCaseSensitiveFileNames: true };
          opts = ts.parseJsonConfigFileContent(raw.config ?? {}, host, dir, {}, c).options;
        } catch {}
        opts = { ...opts, allowJs: true, jsx: ts.JsxEmit.Preserve, module: ts.ModuleKind.ESNext, moduleResolution: ts.ModuleResolutionKind.Bundler, noEmit: true };
        delete opts.rootDirs; delete opts.types;
        cfgCache.set(c, opts);
      }
      return cfgCache.get(c);
    }
    if (dir === root) break;
    dir = path.dirname(dir);
  }
  return { allowJs: true, jsx: ts.JsxEmit.Preserve, module: ts.ModuleKind.ESNext, moduleResolution: ts.ModuleResolutionKind.Bundler };
}

const EXTS = ['.ts', '.tsx', '.js', '.jsx', '.mts'];
function tryFile(base) {
  for (const x of ['', ...EXTS]) { const f = base + x; if (x !== '' || /\.(tsx?|jsx?|mts)$/.test(base)) { try { if (fs.statSync(f).isFile()) return f; } catch {} } }
  for (const x of EXTS) { const f = path.join(base, 'index' + x); try { if (fs.statSync(f).isFile()) return f; } catch {} }
  return null;
}
const modCache = new Map();
let unresolvedExternal = 0;
function resolveModule(from, spec) {
  const key = path.dirname(from) + '\0' + spec;
  if (modCache.has(key)) return modCache.get(key);
  let res = null;
  try {
    const r = ts.resolveModuleName(spec, from, optionsFor(from), ts.sys).resolvedModule;
    if (r && /\.(tsx?|jsx?|mts)$/.test(r.resolvedFileName) && !/\.d\.[cm]?ts$/.test(r.resolvedFileName) && !r.resolvedFileName.includes('/node_modules/')) res = r.resolvedFileName;
  } catch {}
  if (!res && !spec.startsWith('.')) {
    for (const n of wsNames) {
      if (spec === n || spec.startsWith(n + '/')) {
        const dir = ws.get(n), sub = spec.slice(n.length + 1);
        const cands = sub ? [path.join(dir, 'src', sub), path.join(dir, sub)] : [path.join(dir, 'src', 'index'), path.join(dir, 'index'), path.join(dir, 'src', path.basename(dir))];
        for (const c of cands) { const f = tryFile(c); if (f) { res = f; break; } }
        break;
      }
    }
  }
  modCache.set(key, res);
  return res;
}

const infoCache = new Map();
function parseInfo(file) {
  if (infoCache.has(file)) return infoCache.get(file);
  const info = { imports: new Map(), exports: [], stars: [], alias: new Map(), assigns: [] };
  infoCache.set(file, info);
  let text;
  try { text = fs.readFileSync(file, 'utf8'); } catch { return info; }
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, false, /\.(tsx|jsx)$/.test(file) ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
  const has = (n, k) => n.modifiers?.some((m) => m.kind === k);
  const collectAssigns = (node) => {
    if (ts.isBinaryExpression(node) && node.operatorToken.kind === ts.SyntaxKind.EqualsToken && ts.isPropertyAccessExpression(node.left) && ts.isIdentifier(node.left.expression) && ts.isIdentifier(node.right))
      info.assigns.push({ obj: node.left.expression.text, prop: node.left.name.text, rhs: node.right.text });
    if (ts.isCallExpression(node) && node.expression.getText(sf) === 'Object.assign' && node.arguments.length >= 2 && ts.isIdentifier(node.arguments[0]))
      for (const a of node.arguments.slice(1)) if (ts.isObjectLiteralExpression(a))
        for (const p of a.properties) {
          if (ts.isShorthandPropertyAssignment(p)) info.assigns.push({ obj: node.arguments[0].text, prop: p.name.text, rhs: p.name.text });
          else if (ts.isPropertyAssignment(p) && ts.isIdentifier(p.name) && ts.isIdentifier(p.initializer)) info.assigns.push({ obj: node.arguments[0].text, prop: p.name.text, rhs: p.initializer.text });
        }
    ts.forEachChild(node, collectAssigns);
  };
  for (const st of sf.statements) {
    if (ts.isImportDeclaration(st) && st.importClause && !st.importClause.isTypeOnly && ts.isStringLiteral(st.moduleSpecifier)) {
      const spec = st.moduleSpecifier.text, c = st.importClause;
      if (c.name) info.imports.set(c.name.text, { spec, imported: 'default' });
      if (c.namedBindings) {
        if (ts.isNamespaceImport(c.namedBindings)) info.imports.set(c.namedBindings.name.text, { spec, imported: '*' });
        else for (const el of c.namedBindings.elements) if (!el.isTypeOnly) info.imports.set(el.name.text, { spec, imported: (el.propertyName ?? el.name).text });
      }
    } else if (ts.isExportDeclaration(st) && !st.isTypeOnly) {
      const spec = st.moduleSpecifier && ts.isStringLiteral(st.moduleSpecifier) ? st.moduleSpecifier.text : null;
      if (!st.exportClause) { if (spec) info.stars.push(spec); }
      else if (ts.isNamedExports(st.exportClause)) for (const el of st.exportClause.elements) {
        if (el.isTypeOnly) continue;
        const imported = (el.propertyName ?? el.name).text;
        info.exports.push(spec ? { exportName: el.name.text, from: spec, imported } : { exportName: el.name.text, local: imported });
      }
    } else if (ts.isExportAssignment(st) && !st.isExportEquals) {
      info.exports.push({ exportName: 'default', local: ts.isIdentifier(st.expression) ? st.expression.text : null });
    } else if (ts.isVariableStatement(st)) {
      for (const d of st.declarationList.declarations) if (ts.isIdentifier(d.name)) {
        if (has(st, ts.SyntaxKind.ExportKeyword)) info.exports.push({ exportName: d.name.text, local: d.name.text });
        if (d.initializer && ts.isIdentifier(d.initializer)) info.alias.set(d.name.text, d.initializer.text);
      }
    } else if ((ts.isFunctionDeclaration(st) || ts.isClassDeclaration(st)) && has(st, ts.SyntaxKind.ExportKeyword)) {
      const dflt = has(st, ts.SyntaxKind.DefaultKeyword);
      if (st.name) info.exports.push({ exportName: dflt ? 'default' : st.name.text, local: st.name.text });
      else if (dflt) info.exports.push({ exportName: 'default', local: null });
    }
    collectAssigns(st);
  }
  return info;
}

function resolveExport(file, name, depth = 0, seen = new Set()) {
  const k = file + '#' + name;
  if (depth > 20 || seen.has(k)) return null;
  seen.add(k);
  const info = parseInfo(file);
  const chain = [[file, name]];
  const e = info.exports.find((x) => x.exportName === name);
  if (e) {
    if (e.from) {
      const t = resolveModule(file, e.from);
      if (!t) return chain;
      const r = resolveExport(t, e.imported, depth + 1, seen);
      return r ? chain.concat(r) : chain;
    }
    if (e.local) { const r = resolveLocal(file, e.local, depth + 1, seen); return r.chain ? chain.concat(r.chain) : chain; }
    return chain;
  }
  if (name !== 'default') for (const s of info.stars) {
    const t = resolveModule(file, s);
    if (!t) continue;
    const r = resolveExport(t, name, depth + 1, seen);
    if (r) return chain.concat(r);
  }
  return null;
}

// -> { chain } or { ns: file } or { external: spec }
function resolveLocal(file, id, depth = 0, seen = new Set()) {
  if (depth > 20) return {};
  const info = parseInfo(file);
  const imp = info.imports.get(id);
  if (imp) {
    const t = resolveModule(file, imp.spec);
    if (!t) return { external: imp.spec };
    if (imp.imported === '*') return { ns: t };
    const r = resolveExport(t, imp.imported, depth + 1, seen);
    return r ? { chain: r } : { chain: [[t, imp.imported]] };
  }
  const own = info.exports.filter((x) => x.local === id && !x.from);
  if (own.length) return { chain: own.map((x) => [file, x.exportName]) .slice(0, 1) };
  const al = info.alias.get(id);
  if (al && al !== id) return resolveLocal(file, al, depth + 1, seen);
  return { local: [file, id] };
}

function resolveTag(file, tag) {
  const parts = tag.split('.');
  let r = resolveLocal(file, parts[0]);
  for (const prop of parts.slice(1)) {
    if (r.external) return r;
    if (r.ns) { const c = resolveExport(r.ns, prop); r = c ? { chain: c } : { external: 'ns:' + prop }; continue; }
    const pos = r.chain ? r.chain[r.chain.length - 1] : r.local;
    if (!pos) return {};
    const info = parseInfo(pos[0]);
    const a = info.assigns.find((x) => x.prop === prop);
    if (a) r = resolveLocal(pos[0], a.rhs);
    else r = { chain: [[pos[0], pos[1] + '.' + prop]] };
  }
  return r;
}

const sites = [];
const stat = { files: jsxFiles.length, capTags: 0, resolvedToSource: 0, external: 0, localOnly: 0, ns: 0 };
const tagCache = new Map();
for (const file of jsxFiles) {
  let text;
  try { text = fs.readFileSync(file, 'utf8'); } catch { continue; }
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, false, ts.ScriptKind.TSX);
  const visit = (node) => {
    if (ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) {
      const tag = node.tagName.getText(sf);
      if (/^[A-Z]/.test(tag)) {
        stat.capTags++;
        const ck = file + '\0' + tag;
        if (!tagCache.has(ck)) tagCache.set(ck, resolveTag(file, tag));
        const r = tagCache.get(ck);
        if (r.chain) {
          stat.resolvedToSource++;
          const attrs = []; let spreads = 0;
          for (const a of node.attributes.properties) {
            if (ts.isJsxSpreadAttribute(a)) spreads++;
            else attrs.push(a.name.getText(sf));
          }
          sites.push({ file, chain: r.chain, attrs, spreads });
        } else if (r.external) stat.external++;
        else if (r.ns) stat.ns++;
        else stat.localOnly++;
      }
    }
    ts.forEachChild(node, visit);
  };
