function resolveLocal(file, id, depth = 0, seen = new Set()) {
  if (depth > 20) return {};
  const info = parseInfo(file);
  const imp = info.imports.get(id);
  if (imp) {
    const t = resolveModule(file, imp.spec);
    if (!t) return { external: imp.spec };
    if (imp.imported === '*') return { ns: t };
    const r = resolveExport(t, imp.imported, depth + 1, seen);
    return r ? { chain: r } : { chain: [[t, imp.imported]] };
