const storyOut = [];
for (const file of stories) {
  let text; try { text = fs.readFileSync(file, 'utf8'); } catch { continue; }
  if (!/\.(tsx|ts|jsx|js)$/.test(file)) continue;
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, false, ts.ScriptKind.TSX);
  let comp = null; const argSets = [];
  const visit = (n) => {
    if (ts.isPropertyAssignment(n) && n.name.getText(sf) === 'component' && ts.isIdentifier(n.initializer)) comp = n.initializer.text;
    if (ts.isPropertyAssignment(n) && n.name.getText(sf) === 'args' && ts.isObjectLiteralExpression(n.initializer))
