import json, sys, re, statistics, collections, os

R = '/Users/gabe/Projects/caliper-fixtures/shrink/relevance/out'
CORPORA = [  # name, sites file, srcdir (library source for the "external only" variant), outputs
    ('mantine', 'mantine', '/corpora/mantine/packages/@mantine/core/src', ['mantine.checker', 'mantine.nochecker']),
    ('react-spectrum', 'spectrum', '/corpora/react-spectrum/packages', ['spectrum.checker', 'spectrum.nochecker']),
    ('shadcn-ui', 'shadcn', '/corpora/shadcn-ui/apps/v4', ['shadcn.checker', 'shadcn.nochecker']),
    ('ant-design', 'antd', '/corpora/ant-design/components', ['antd.checker', 'antd.nochecker']),
    ('chakra-ui', 'chakra', '/corpora/chakra-ui/packages/react/src', ['chakra.nochecker']),
]
BASE = '/Users/gabe/Projects/caliper-fixtures'
DOM_RE = re.compile(r'^(aria-.*|data-.*|on[A-Z].*|className|style|id|role|tabIndex|title|hidden|lang|dir|ref|key|slot|htmlFor|href|target|rel|type|name|value|disabled|placeholder|src|alt|width|height|tabindex)$')
STRICT_RE = re.compile(r'^(aria-.*|data-.*|on[A-Z].*|className|style|id)$')


def pct(xs, p):
    xs = sorted(xs)
    if not xs:
        return 0
    i = min(len(xs) - 1, int(round(p / 100 * (len(xs) - 1))))
    return xs[i]


def analyse(corpus, sites_name, src, out_name, min_sites=3, external_only=False, thresh=None):
    d = json.load(open(f'{R}/{out_name}.json'))
    sd = json.load(open(f'{R}/{sites_name}.sites.json'))
    comps = d['components']
    elems = json.load(open(f'{R}/{out_name}.elems.json')) if os.path.exists(f'{R}/{out_name}.elems.json') else {}
    ident = {}
    for k, v in comps.items():
        for e in v['exports']:
            ident.setdefault((v['filePath'], e['name']), k)
    visible, layers = {}, {}
    for k, v in comps.items():
        vis = set()
        for ps in v['props']:
            vis |= set(d['propSets'].get(ps, {}).keys())
        if isinstance(v['notableInherited'], dict):
            vis |= set(v['notableInherited'].keys())
        else:
            vis |= set(v['notableInherited'] or [])
        visible[k] = vis
        ly = {}
        for l in v['inheritance']:
            lab = f"{l['typeName']}<{l.get('htmlElement') or '-'}>"
            om = l.get('members')
            names = d['nameLists'].get(om, []) if om else []
            if not names and l.get('htmlElement') and elems:
                names = elems.get(l['htmlElement'], [])
            for n in names:
                ly.setdefault(n, lab)
        layers[k] = ly
    srcabs = BASE + src
    bycomp = collections.defaultdict(list)
    matched = 0
    for s in sd['sites']:
        k = None
        for f, n in s['chain']:
            k = ident.get((f, n))
            if k:
                break
        if not k:
            continue
        if external_only and s['file'].startswith(srcabs + '/'):
            continue
        matched += 1
        bycomp[k].append(s)
    rows = []
    hidden_counter = collections.Counter()
    hidden_layer = {}
    for k, ss in bycomp.items():
        if len(ss) < min_sites:
            continue
        cnt = collections.Counter()
        spreads = 0
        for s in ss:
            for a in set(s['attrs']):
                if a != 'key':
                    cnt[a] += 1
            spreads += 1 if s['spreads'] else 0
        passed = set(cnt)
        if thresh:
            need = max(2, int(thresh * len(ss) + 0.999))
            passed = {a for a in passed if cnt[a] >= need}
        if not passed:
            continue
        vis, ly = visible[k], layers[k]
        inv = passed & vis
        hid = {a for a in passed - vis if a in ly}
        nowhere = passed - vis - set(hid)
        tot = sum(cnt[a] for a in passed)
        rows.append(dict(k=k, sites=len(ss), vis=len(vis), passed=len(passed), cov=len(inv) / len(passed),
                         wcov=sum(cnt[a] for a in inv) / tot, hid=hid, nowhere=nowhere, spread_share=spreads / len(ss)))
        for a in hid:
            hidden_counter[a] += 1
            hidden_layer.setdefault(a, ly[a])
    return d, sd, comps, rows, hidden_counter, hidden_layer, matched


def summarize(rows, hc, hl):
    if not rows:
        return None
    vc = [r['vis'] for r in rows]
    hidn = [len(r['hid']) for r in rows]
    strict = sum(n for a, n in hc.items() if STRICT_RE.match(a))
    broad = sum(n for a, n in hc.items() if DOM_RE.match(a))
    tot = sum(hc.values()) or 1
    return dict(n=len(rows), vmed=statistics.median(vc), vp90=pct(vc, 90),
                covmed=statistics.median(r['cov'] for r in rows), wcovmed=statistics.median(r['wcov'] for r in rows),
                covmean=statistics.mean(r['cov'] for r in rows),
                full=sum(1 for r in rows if r['cov'] == 1) / len(rows),
                hmean=statistics.mean(hidn), hmed=statistics.median(hidn), hp90=pct(hidn, 90), hmax=max(hidn),
                zero=sum(1 for h in hidn if h == 0) / len(rows),
                nowhere=statistics.mean(len(r['nowhere']) for r in rows),
                strict=strict / tot, broad=broad / tot, tot=tot,
                spread=statistics.mean(r['spread_share'] for r in rows))


def main():
    md = []
    for corpus, sn, src, outs in CORPORA:
        sd0 = json.load(open(f'{R}/{sn}.sites.json'))
        md.append(f"\n## {corpus}\n")
        md.append(f"Call-site scan: {sd0['stat']['files']} .tsx/.jsx files, {sd0['stat']['capTags']} capitalised JSX tags, "
                  f"{sd0['stat']['resolvedToSource']} resolved to an in-repo source file, {sd0['stat']['external']} to an external package "
                  f"(not in the checkout), {sd0['stat']['localOnly']} to a local non-exported binding. Story files: {len(sd0['stories'])}.\n")
        for out in outs:
            for variant, kw in (('all call sites', {}), ('outside library src only', dict(external_only=True))):
                d, sd, comps, rows, hc, hl, matched = analyse(corpus, sn, src, out, **kw)
                s = summarize(rows, hc, hl)
                md.append(f"### {out} - {variant}\n")
                md.append(f"caliper components: {len(comps)}; call sites matched to a caliper component: {matched}.\n")
                if not s:
                    md.append("No component with >= 3 call sites.\n")
                    continue
                md.append(f"- components measured (>=3 call sites): {s['n']}")
                md.append(f"- visible props per component: median {s['vmed']}, p90 {s['vp90']}")
                md.append(f"- coverage (set of passed names visible): median {s['covmed']:.2f}, mean {s['covmean']:.2f}; call-weighted median {s['wcovmed']:.2f}; components at 100%: {s['full']:.0%}")
                md.append(f"- used-but-hidden props per component (extra rows if surfaced): mean {s['hmean']:.2f}, median {s['hmed']}, p90 {s['hp90']}, max {s['hmax']}; components with none: {s['zero']:.0%}")
                md.append(f"- passed but in no list at all (neither visible nor in a layer), mean per component: {s['nowhere']:.2f}")
                md.append(f"- share of components' call sites with a spread attribute, mean: {s['spread']:.0%}")
                md.append(f"- hidden-used (component, prop) pairs: {s['tot']}; DOM/ARIA strict (className, style, id, aria-*, data-*, on*): {s['strict']:.0%}; broad (plus role, tabIndex, title, href, type, name, value, disabled ... ): {s['broad']:.0%}")
                md.append("- top 15 used-but-hidden props (components where the prop is passed but hidden; layer):")
                for a, n in hc.most_common(15):
                    md.append(f"  - {a}: {n} components ({hl[a]})")
                # cost curve on thresholds
                for th in (0.2, 0.5):
                    _, _, _, rows2, hc2, hl2, _ = analyse(corpus, sn, src, out, thresh=th, **kw)
                    s2 = summarize(rows2, hc2, hl2)
                    if s2:
                        md.append(f"- rule 'only props passed at >= max(2, {int(th*100)}% of sites)': extra rows mean {s2['hmean']:.2f}, median {s2['hmed']}, p90 {s2['hp90']}; coverage median {s2['covmed']:.2f}")
                md.append("")
    open('/Users/gabe/Projects/caliper-fixtures/shrink/relevance/results.md', 'w').write('\n'.join(md))
    print('\n'.join(md))


main()

